                    # ==========================================================
                    # 1. INITIALIZATION & DYNAMIC CONFIGURATION
                    # ==========================================================
                    #
                    # WARNING SERVER SCRIPT PLACEMENT (Quotation DocType)
                    # Bind this script to event **Before Validate** - not Before Save.
                    #
                    # Frappe runs: before_validate <= validate (India Compliance GST checks) <= before_save.
                    # If CUSTOM-FABRIC rows are still placeholders at validate-time, the document often has
                    # Output GST while rows look "non-taxable" (no Item Tax Template) <=
                    # "Cannot charge GST on Non-Taxable Items." Converting items here fixes that for all companies.
                    #
                    # WARNING ONE SERVER SCRIPT PER EVENT: Each Server Script = separate namespace (no shared defs).
                    # Paste this file as a single script at COLUMN 0 (no leading spaces on the first line).
                    # Disable other Quotation / Before Validate Server Scripts or you will keep seeing
                    # "create_plain_sheet_fabric_bom_and_sheet_bom is not defined".
                    # Avoid tuple unpacking (a, b = ...): RestrictedPython raises name '_unpack_sequence_' is not defined.
                    #
                    try:
                        companies = frappe.get_all("Company", pluck="name")
                        with open("c:/Users/Admin/Documents/Code/Quotation item creation/companies_list.txt", "w") as f:
                            f.write("\n".join(companies))
                    except Exception:
                        pass

                    process_records = frappe.get_all("Process Master", fields=["process_name", "process_code"])
                    process_config = {str(p.get("process_name")).upper(): str(p.get("process_code")).zfill(3) for p in process_records}
                    process_rev = {str(p.get("process_code")).zfill(3): str(p.get("process_name")) for p in process_records}
                    possible_process_codes = tuple(process_rev.keys()) if process_rev else ("100",)

                    PLACEHOLDER_ITEM = "CUSTOM-FABRIC"

                    def resolve_design_item_code_prefix(design_link, default_prefix="2500"):
                        """Numeric prefix for item/BOM codes from DESIGN MASTER link (doc name or design_name field)."""
                        link = str(design_link or "").strip()
                        if not link:
                            return str(default_prefix)
                        try:
                            if frappe.db.exists("DESIGN MASTER", link):
                                dn = frappe.db.get_value("DESIGN MASTER", link, "design_name")
                                if dn is not None:
                                    ds = str(dn).strip()
                                    if ds.isdigit():
                                        return ds
                                if link.isdigit():
                                    return link
                                if str(link).upper() in ("PLAIN D-CUT", "PLAIN D-CUT BAG"):
                                    return str(default_prefix)
                                return link
                            if link.isdigit():
                                return link
                        except Exception:
                            pass
                        return str(default_prefix)

                    def normalize_d_cut_design_link(row, doc=None):
                        """custom_design_code is a Link — use DESIGN MASTER doc name, not numeric design_name 2500."""
                        p = str(row.get("custom_process") or row.get("process") or "").strip().upper()
                        is_d_cut_flexo = "D CUT PRINTED FLEXO" in p.replace("-", " ") or "D-CUT PRINTED FLEXO" in p
                        is_d_cut_laminated = (
                            ("D CUT LAMINATED" in p.replace("-", " ") or "D-CUT LAMINATED" in p)
                            and "PRINTED" not in p
                        )
                        is_d_cut_laminated_printed = (
                            ("D CUT LAMINATED PRINTED" in p.replace("-", " ") or "D-CUT LAMINATED PRINTED" in p)
                        )
                        is_d_cut_bopp_roto = (
                            ("D CUT BOPP ROTO" in p.replace("-", " ") or "D-CUT BOPP ROTO" in p)
                        )
                        is_d_cut_mettalic_roto = (
                            ("D CUT METTALIC ROTO" in p.replace("-", " ") or "D-CUT METTALIC ROTO" in p)
                        )
                        is_d_cut = (
                            "D CUT PLAIN" in p.replace("-", " ") or "D-CUT PLAIN" in p or is_d_cut_flexo or is_d_cut_laminated or is_d_cut_laminated_printed or is_d_cut_bopp_roto or is_d_cut_mettalic_roto or
                            (("D CUT" in p or "D-CUT" in p) and "PLAIN" in p and "BOX BAG" not in p and "SHOPPER BAG" not in p)
                        )
                        if not is_d_cut and doc:
                            bag_type = str(doc.get("custom_type_of_bag") or "").lower()
                            if "d-cut" in bag_type or "d cut" in bag_type:
                                is_d_cut = True
                        if not is_d_cut:
                            return
                        dc = str(row.get("custom_design_code") or "").strip()
                        hint = str(row.get("custom_design_name") or "").strip()
                        if dc in ("2500", "6000") and not frappe.db.exists("DESIGN MASTER", dc):
                            resolved = resolve_design_master_doc_name(dc, hint)
                            if not resolved:
                                resolved = resolve_design_master_doc_name("", hint)
                            if resolved:
                                row.custom_design_code = resolved
                            elif frappe.db.exists("DESIGN MASTER", "PLAIN D-CUT"):
                                row.custom_design_code = "PLAIN D-CUT"
                            else:
                                row.custom_design_code = ""
                        if not is_d_cut_flexo and not is_d_cut_laminated and not is_d_cut_laminated_printed and not is_d_cut_bopp_roto:
                            dn = str(row.get("custom_design_name") or "").strip().upper()
                            if not dn or dn in ("2500", "PLAIN D-CUT BAG", "PLAIN BOX BAG"):
                                row.custom_design_name = "PLAIN D-CUT"

                    def read_tag_from_description(desc, tag_name):
                        desc = str(desc or "")
                        marker = "||" + str(tag_name) + ":"
                        start = desc.find(marker)
                        if start < 0:
                            return ""
                        start += len(marker)
                        end = desc.find("||", start)
                        if end < 0:
                            return desc[start:].strip()
                        return desc[start:end].strip()

                    def strip_description_tag(desc, tag_name):
                        text = str(desc or "")
                        marker = "||" + str(tag_name) + ":"
                        while True:
                            start = text.find(marker)
                            if start < 0:
                                break
                            end = text.find("||", start + len(marker))
                            if end < 0:
                                text = text[:start].strip()
                                break
                            text = (text[:start] + text[end + 2:]).strip()
                        return text

                    def persist_flexo_design_fields_to_description(row):
                        """Keep design link / colours in description when grid columns are hidden on save."""
                        desc = strip_description_tag(
                            strip_description_tag(
                                strip_description_tag(row.get("description"), "DESIGN_MASTER"),
                                "DESIGN_COLOUR",
                            ),
                            "NO_OF_DESIGN_COLOUR",
                        )
                        parts = []
                        link = str(row.get("custom_design_code") or "").strip()
                        dc = str(row.get("custom_design_colour") or "").strip()
                        noc = str(
                            row.get("custom_no_of_design_colour") or row.get("custom_no_of_design_colours") or ""
                        ).strip()
                        if link:
                            parts.append("||DESIGN_MASTER:" + link + "||")
                        if dc:
                            parts.append("||DESIGN_COLOUR:" + dc + "||")
                        if noc and noc not in ("0", "0.0"):
                            parts.append("||NO_OF_DESIGN_COLOUR:" + noc + "||")
                        if parts:
                            try:
                                row.description = (desc + " " + " ".join(parts)).strip() if desc else " ".join(parts)
                            except Exception:
                                pass

                    def resolve_design_master_from_item_prefix(prefix):
                        px = str(prefix or "").strip()
                        if not px:
                            return ""
                        if frappe.db.exists("DESIGN MASTER", px):
                            return px
                        try:
                            found = frappe.db.get_value("DESIGN MASTER", {"design_name": px}, "name")
                        except Exception:
                            found = None
                        if found:
                            return str(found).strip()
                        if px.isdigit():
                            try:
                                found = frappe.db.get_value(
                                    "DESIGN MASTER", {"design_name": ["like", "%" + px + "%"]}, "name"
                                )
                            except Exception:
                                found = None
                            if found:
                                return str(found).strip()
                        return ""

                    def ensure_valid_design_master_link_on_row(row):
                        """Link field must be a DESIGN MASTER doc name — never leave invalid numeric-only values."""
                        restore_flexo_design_fields_from_description(row)
                        link = str(row.get("custom_design_code") or "").strip()
                        hint = str(row.get("custom_design_name") or "").strip()
                        master = resolve_design_master_doc_name(link, hint)
                        if not master and link:
                            master = resolve_design_master_from_item_prefix(link)
                        if master:
                            try:
                                row.custom_design_code = master
                            except Exception:
                                pass
                        sync_design_fields_from_master(row)
                        persist_flexo_design_fields_to_description(row)

                    def decode_plain_w_cut_bag_row_from_item_code(row, code):
                        """Restore design link from plain W-Cut bag item code (PREFIX-SIZE-200...)."""
                        ic = str(code or "").strip()
                        if "-200" not in ic.upper():
                            return
                        parts = ic.split("-")
                        if len(parts) < 3:
                            return
                        prefix = parts[0]
                        master = resolve_design_master_from_item_prefix(prefix)
                        if master:
                            try:
                                row.custom_design_code = master
                            except Exception:
                                pass
                        try:
                            row.custom_bag_size = row.custom_bag_size or parts[1]
                        except Exception:
                            pass
                        ensure_valid_design_master_link_on_row(row)

