                    def decode_d_cut_laminated_bag_row_from_item_code(row, code):
                        """Restore design link from D-Cut laminated bag item code (213 plain / 214 printed)."""
                        ic = str(code or "").strip()
                        ic_upper = ic.upper()
                        if "-213" not in ic_upper and "-214" not in ic_upper:
                            return
                        parts = ic.split("-")
                        if len(parts) < 3:
                            return
                        prefix = parts[0]
                        color_part = parts[1] if len(parts) > 3 else ""
                        master = resolve_design_master_from_item_prefix(prefix)
                        if master:
                            try:
                                row.custom_design_code = master
                            except Exception:
                                pass
                        if color_part and str(color_part).upper().endswith("C"):
                            noc = str(color_part)[:-1]
                            if noc.isdigit():
                                try:
                                    row.custom_no_of_design_colour = noc
                                    row.custom_no_of_design_colours = noc
                                except Exception:
                                    pass
                        try:
                            bag_size_part = parts[2] if len(parts) > 3 else parts[1]
                            row.custom_bag_size = row.custom_bag_size or bag_size_part
                        except Exception:
                            pass
                        try:
                            tail = parts[3] if len(parts) > 3 else parts[2]
                            if isinstance(tail, str) and (tail.startswith("213") or tail.startswith("214")) and len(tail) >= 10:
                                lam_char = tail[9]
                                lam_gsm_map_rev = {
                                    "A": "10 - A",
                                    "B": "12 - B",
                                    "C": "15 - C",
                                    "D": "30 - D",
                                    "E": "20 - E",
                                }
                                lam_val = lam_gsm_map_rev.get(str(lam_char or "").upper())
                                if lam_val:
                                    row.custom_lamination_gsm = lam_val
                                    if not row.get("custom_lamination_side"):
                                        row.custom_lamination_side = "Outer Lamination"
                                    try:
                                        total_gsm = int(float(row.get("custom_gsm") or 0))
                                        lam_num = int(str(lam_val).split("-")[0].strip())
                                        if total_gsm > 0:
                                            row.custom_fabric_gsm = max(0, total_gsm - lam_num)
                                    except Exception:
                                        pass
                        except Exception:
                            pass
                        ensure_valid_design_master_link_on_row(row)


                    def ensure_d_cut_laminated_gsm_fields(row):
                        if not row:
                            return
                        try:
                            lam_raw = str(row.get("custom_lamination_gsm") or "").strip()
                            if not lam_raw:
                                lam_raw = "10 - A"
                                row.custom_lamination_gsm = lam_raw
                            if not str(row.get("custom_lamination_side") or "").strip():
                                row.custom_lamination_side = "Outer Lamination"
                            lam_num = 0
                            lam_digits = "".join(ch for ch in lam_raw if ch.isdigit())
                            if lam_digits:
                                lam_num = int(lam_digits)
                            total_gsm = int(float(row.get("custom_gsm") or 0))
                            fabric_gsm = int(float(row.get("custom_fabric_gsm") or 0))
                            if total_gsm > 0:
                                calc_fabric = max(0, total_gsm - lam_num)
                                if fabric_gsm <= 0:
                                    row.custom_fabric_gsm = calc_fabric
                        except Exception:
                            pass

                    def restore_flexo_design_fields_from_description(row):
                        desc = str(row.get("description") or "")
                        if not str(row.get("custom_design_code") or "").strip():
                            dm = read_tag_from_description(desc, "DESIGN_MASTER")
                            if dm:
                                try:
                                    row.custom_design_code = dm
                                except Exception:
                                    pass
                        if not str(row.get("custom_design_colour") or "").strip():
                            dc = read_tag_from_description(desc, "DESIGN_COLOUR")
                            if dc:
                                try:
                                    row.custom_design_colour = dc
                                except Exception:
                                    pass
                        noc_raw = str(
                            row.get("custom_no_of_design_colour") or row.get("custom_no_of_design_colours") or ""
                        ).strip()
                        if not noc_raw or noc_raw in ("0", "0.0"):
                            noc = read_tag_from_description(desc, "NO_OF_DESIGN_COLOUR")
                            if noc:
                                try:
                                    row.custom_no_of_design_colour = noc
                                    row.custom_no_of_design_colours = noc
                                except Exception:
                                    pass

                    def parse_design_colour_names(colour_raw):
                        names = []
                        raw = str(colour_raw or "").strip()
                        if not raw:
                            return names
                        try:
                            parsed_num = int(float(raw))
                            if parsed_num > 0:
                                return names
                        except (ValueError, TypeError):
                            pass
                        normalized = raw.replace("&", "\n").replace(",", "\n")
                        for colour_part in normalized.split("\n"):
                            colour_part = colour_part.strip()
                            if not colour_part:
                                continue
                            j = 0
                            while j < len(colour_part) and colour_part[j].isdigit():
                                j += 1
                            if j < len(colour_part) and colour_part[j] == ".":
                                colour_part = colour_part[j + 1 :].strip()
                            if colour_part:
                                names.append(colour_part)
                        return names

                    def resolve_bag_no_colors_for_row(row):
                        restore_flexo_design_fields_from_description(row)
                        sync_design_fields_from_master(row)
                        bag_no_colors_raw = str(
                            row.get("custom_no_of_design_colour") or row.get("custom_no_of_design_colours") or ""
                        ).strip()
                        if bag_no_colors_raw in ("", "0", "0.0"):
                            pb_cols = parse_design_colour_names(row.get("custom_design_colour"))
                            if pb_cols:
                                bag_no_colors_raw = str(len(pb_cols))
                            else:
                                bag_no_colors_raw = "1"
                        if bag_no_colors_raw.endswith(".0") and bag_no_colors_raw[:-2].isdigit():
                            bag_no_colors_raw = bag_no_colors_raw[:-2]
                        return f"{bag_no_colors_raw}C" if bag_no_colors_raw.isdigit() else bag_no_colors_raw

                    def design_master_field_value(master_name, candidates):
                        for fieldname in candidates:
                            try:
                                if not frappe.get_meta("DESIGN MASTER").has_field(fieldname):
                                    continue
                            except Exception:
                                continue
                            try:
                                val = frappe.db.get_value("DESIGN MASTER", master_name, fieldname)
                            except Exception:
                                val = None
                            if val is not None and str(val).strip() != "":
                                return val
                        return None

                    def design_colours_from_master_children(master_name):
                        """Build comma-separated colour list from DESIGN MASTER child tables."""
                        colours = []
                        try:
                            dm_meta = frappe.get_meta("DESIGN MASTER")
                            for df in dm_meta.fields:
                                if df.fieldtype != "Table" or not df.options:
                                    continue
                                child_dt = df.options
                                try:
                                    child_meta = frappe.get_meta(child_dt)
                                except Exception:
                                    continue
                                colour_fieldnames = []
                                for cf in child_meta.fields:
                                    fn = str(cf.fieldname or "").lower()
                                    if ("colour" in fn or "color" in fn) and "no_of" not in fn and "count" not in fn:
                                        if cf.fieldtype in ("Data", "Small Text", "Text", "Select", "Link"):
                                            colour_fieldnames.append(cf)
                                if not colour_fieldnames:
                                    continue
                                fetch_fields = [cf.fieldname for cf in colour_fieldnames]
                                rows = frappe.get_all(
                                    child_dt,
                                    filters={
                                        "parent": master_name,
                                        "parenttype": "DESIGN MASTER",
                                        "parentfield": df.fieldname,
                                    },
                                    fields=fetch_fields,
                                    order_by="idx asc",
                                    limit_page_length=30,
                                )
                                for row in rows or []:
                                    for cf in colour_fieldnames:
                                        val = str(row.get(cf.fieldname) or "").strip()
                                        if not val:
                                            continue
                                        if cf.fieldtype == "Link" and cf.options:
                                            link_dt = cf.options
                                            resolved = ""
                                            for label_fn in ("colour_name", "color_name", "name"):
                                                try:
                                                    if frappe.get_meta(link_dt).has_field(label_fn):
                                                        resolved = frappe.db.get_value(link_dt, val, label_fn)
                                                except Exception:
                                                    resolved = ""
                                                if resolved:
                                                    break
                                            val = str(resolved or val).strip()
                                        if val and val not in colours:
                                            colours.append(val)
                        except Exception:
                            pass
                        if colours:
                            return ", ".join(colours)
                        return ""

                    def design_colours_text_from_master(master_name):
                        """Parent field or child-table colours for DESIGN MASTER."""
                        parent_val = design_master_field_value(
                            master_name,
                            [
                                "design_colour",
                                "custom_design_colour",
                                "design_color",
                                "custom_design_color",
                                "design_colours",
                                "custom_design_colours",
                                "colours",
                                "colors",
                            ],
                        )
                        if parent_val:
                            return str(parent_val).strip()
                        child_val = design_colours_from_master_children(master_name)
                        if child_val:
                            return child_val
                        fallback_colours = []
                        try:
                            doc = frappe.get_doc("DESIGN MASTER", master_name)
                            for key, val in doc.as_dict().items():
                                if not isinstance(val, list) or not val:
                                    continue
                                if not isinstance(val[0], dict):
                                    continue
                                for child_row in val:
                                    if not isinstance(child_row, dict):
                                        continue
                                    for fn, cell in child_row.items():
                                        fnl = str(fn or "").lower()
                                        if ("colour" not in fnl and "color" not in fnl) or "no_of" in fnl:
                                            continue
                                        cell_s = str(cell or "").strip()
                                        if cell_s and cell_s not in fallback_colours:
                                            fallback_colours.append(cell_s)
                        except Exception:
                            pass
                        if fallback_colours:
                            return ", ".join(fallback_colours)
                        return ""

                    def resolve_design_master_doc_name(design_link, design_name_hint=None):
                        link = str(design_link or "").strip()
                        hint = str(design_name_hint or "").strip()
                        if link and frappe.db.exists("DESIGN MASTER", link):
                            return link
                        for candidate in (link, hint):
                            if not candidate:
                                continue
                            try:
                                found = frappe.db.get_value("DESIGN MASTER", {"design_name": candidate}, "name")
                            except Exception:
                                found = None
                            if found:
                                return str(found).strip()
                            if candidate.isdigit():
                                try:
                                    found = frappe.db.get_value(
                                        "DESIGN MASTER", {"design_name": ["like", "%" + candidate + "%"]}, "name"
                                    )
                                except Exception:
                                    found = None
                                if found:
                                    return str(found).strip()
                        return link if link and frappe.db.exists("DESIGN MASTER", link) else ""

                    def sync_design_fields_from_master(row):
                        """Fill design name / colour / colour count from DESIGN MASTER when missing on the row."""
                        restore_flexo_design_fields_from_description(row)
                        link = str(row.get("custom_design_code") or "").strip()
                        hint = str(row.get("custom_design_name") or "").strip()
                        master_name = resolve_design_master_doc_name(link, hint)
                        if not master_name:
                            return
                        if master_name != link:
                            try:
                                row.custom_design_code = master_name
                            except Exception:
                                pass
                        dn = design_master_field_value(
                            master_name, ["design_name", "custom_design_name"]
                        )
                        placeholder_design_names = ("", "2500", "PLAIN D-CUT", "PLAIN D-CUT BAG", "PLAIN BOX BAG")
                        if dn:
                            cur_dn = str(row.get("custom_design_name") or "").strip().upper()
                            if not cur_dn or cur_dn in placeholder_design_names:
                                try:
                                    row.custom_design_name = str(dn).strip()
                                except Exception:
                                    pass
                        if not str(row.get("custom_design_colour") or "").strip():
                            dc = design_colours_text_from_master(master_name)
                            if dc:
                                try:
                                    row.custom_design_colour = str(dc).strip()
                                except Exception:
                                    pass
                        noc = design_master_field_value(
                            master_name,
                            [
                                "no_of_design_colours",
                                "no_of_design_colour",
                                "custom_no_of_design_colours",
                                "custom_no_of_design_colour",
                            ],
                        )
                        if noc is not None and str(noc).strip() != "":
                            if not str(row.get("custom_no_of_design_colour") or "").strip():
                                try:
                                    row.custom_no_of_design_colour = noc
                                except Exception:
                                    pass
                            if not str(row.get("custom_no_of_design_colours") or "").strip():
                                try:
                                    row.custom_no_of_design_colours = noc
                                except Exception:
                                    pass

                    # Flexo printing uses non-woven/flexo inks only — never BOPP INK - 001..009.
                    FLEXO_INK_GSM_ADD = 0.32
                    FLEXO_ISOBUTANOL_GSM_ADD = 0.435
                    FLEXO_BOPP_INK_CODES = {
                        "INK - 001", "INK - 002", "INK - 003", "INK - 004", "INK - 005",
                        "INK - 006", "INK - 007", "INK - 008", "INK - 009",
                    }
                    FLEXO_BOPP_SOLVENT_CODES = {"CM - 5003001", "CM - 5003002", "CM - 5003004"}

                    FLEXO_ISOBUTANOL_ITEM = "INK - 1007091"

                    def is_flexo_isobutanol_item(item_code):
                        return str(item_code or "").strip().upper() == FLEXO_ISOBUTANOL_ITEM

                    def is_flexo_colour_ink_item(item_code, item_name=None):
                        """Flexo colour inks use item codes INK - 100xxxx (not isobutanol 1007091)."""
                        code_up = str(item_code or "").strip().upper()
                        if not code_up or is_flexo_isobutanol_item(code_up):
                            return False
                        return code_up.startswith("INK - 100")

                    def is_nonwoven_fabric_item_code(item_code):
                        ic = str(item_code or "").strip()
                        return ic.isdigit() and len(ic) >= 12 and ic.startswith("100")

                    def pick_first_existing_item(candidates):
                        for code in candidates or []:
                            c = str(code or "").strip()
                            if c and frappe.db.exists("Item", c):
                                return c
                        return None

                    def is_bopp_ink_item(item_code, item_name=None):
                        code_up = str(item_code or "").strip().upper()
                        name_up = str(item_name or "").strip().upper()
                        if code_up in FLEXO_BOPP_INK_CODES:
                            return True
                        if "BOPP INK" in name_up:
                            return True
                        return False

                    def pick_first_flexo_ink_item(candidates):
                        for code in candidates or []:
                            c = str(code or "").strip()
                            if not c or is_flexo_isobutanol_item(c) or is_bopp_ink_item(c):
                                continue
                            if frappe.db.exists("Item", c):
                                item_name = frappe.db.get_value("Item", c, "item_name")
                                if is_flexo_colour_ink_item(c, item_name) and not is_nonwoven_fabric_item_code(c):
                                    return c
                        return None

                    def list_flexo_colour_ink_items():
                        rows = frappe.get_all(
                            "Item",
                            filters={"disabled": 0, "name": ["like", "INK - 100%"]},
                            fields=["name", "item_name"],
                            order_by="name",
                            limit_page_length=100,
                        )
                        out = []
                        for r in rows or []:
                            nm = str(r.get("name") or "").strip()
                            if is_flexo_colour_ink_item(nm, r.get("item_name")):
                                out.append(nm)
                        return out

                    def pick_default_flexo_ink_items(colour_count):
                        all_inks = list_flexo_colour_ink_items()
                        if not all_inks:
                            return []
                        chosen = []
                        for ic in all_inks:
                            inm = str(frappe.db.get_value("Item", ic, "item_name") or "").upper()
                            if "BLACK" in inm:
                                chosen.append(ic)
                                break
                        for ic in all_inks:
                            if ic not in chosen:
                                chosen.append(ic)
                            if len(chosen) >= max(int(colour_count or 1), 1):
                                break
                        need = max(int(colour_count or 1), 1)
                        return chosen[:need]

                    def parse_flexo_design_colours(row):
                        raw = str(row.get("custom_design_colour") or "").strip()
                        colours = []
                        if not raw:
                            return colours
                        try:
                            parsed_num = int(float(raw))
                            if parsed_num > 0:
                                return colours
                        except (ValueError, TypeError):
                            pass
                        normalized = raw.replace("&", "\n").replace(",", "\n")
                        for colour_part in normalized.split("\n"):
                            colour_part = colour_part.strip()
                            if not colour_part:
                                continue
                            idx = 0
                            while idx < len(colour_part) and colour_part[idx].isdigit():
                                idx += 1
                            if idx < len(colour_part) and colour_part[idx] == ".":
                                colour_part = colour_part[idx + 1 :].strip()
                            if colour_part:
                                colours.append(colour_part)
                        return colours

                    def flexo_ink_candidates_for_colour(colour_upper):
                        """Return INK - 100* flexo ink item codes matching the design colour text."""
                        if not colour_upper:
                            return []
                        tokens = []
                        for tok in colour_upper.replace("/", " ").replace("-", " ").replace("&", " ").split():
                            tok = tok.strip()
                            if len(tok) >= 3:
                                tokens.append(tok)
                        tokens.sort(key=len, reverse=True)
                        found = []
                        all_flexo = list_flexo_colour_ink_items()
                        for tok in tokens:
                            tok_up = tok.upper()
                            for ic in all_flexo:
                                inm = str(frappe.db.get_value("Item", ic, "item_name") or "").upper()
                                if tok_up in inm and ic not in found:
                                    found.append(ic)
                        if found:
                            return found
                        keyword_map = [
                            (["BLACK"], ["BLACK"]),
                            (["WHITE"], ["WHITE"]),
                            (["YELLOW", "GOLDEN", "GOLD"], ["YELLOW", "GOLD"]),
                            (["CYAN", "AQUA"], ["CYAN", "AQUA"]),
                            (["MAGENTA", "MEGENTA", "PINK"], ["MAGENTA", "MEGENDA", "PINK"]),
                            (["RED", "MAROON"], ["RED", "MAROON"]),
                            (["ORANGE"], ["ORANGE"]),
                            (["GREEN", "PARROT"], ["GREEN", "PARROT"]),
                            (["BLUE", "ROYAL"], ["BLUE", "ROYAL"]),
                            (["VIOLET", "PURPLE"], ["VIOLET", "PURPLE"]),
                            (["GREY", "GRAY"], ["GREY", "GRAY"]),
                            (["BROWN"], ["BROWN"]),
                            (["CREAM"], ["CREAM"]),
                            (["TRANSPARENT", "TRPT", "TRANS"], ["TRPT", "TRANS", "TRANSPARENT"]),
                        ]
                        for kw_list, name_bits in keyword_map:
                            for kw in kw_list:
                                if kw in colour_upper:
                                    for ic in all_flexo:
                                        inm = str(frappe.db.get_value("Item", ic, "item_name") or "").upper()
                                        if any(bit in inm for bit in name_bits) and ic not in found:
                                            found.append(ic)
                                    if found:
                                        return found
                        return found

                    def search_flexo_ink_item_by_name(colour_upper):
                        return (flexo_ink_candidates_for_colour(colour_upper) or [None])[0]

                    def resolve_flexo_ink_parts(row):
                        sync_design_fields_from_master(row)
                        colours = parse_flexo_design_colours(row)
                        ink_parts = {}
                        no_of_raw = str(row.get("custom_no_of_design_colours") or row.get("custom_no_of_design_colour") or "").strip()
                        colour_count = 0
                        if no_of_raw:
                            try:
                                colour_count = int(float(no_of_raw))
                            except (ValueError, TypeError):
                                colour_count = 0
                        if colour_count <= 0 and colours:
                            colour_count = len(colours)
                        if colour_count <= 0:
                            colour_count = 1

                        for colour in colours:
                            c_up = colour.strip().upper()
                            found_codes = flexo_ink_candidates_for_colour(c_up)
                            resolved = []
                            for code in found_codes:
                                if code and code not in resolved and is_flexo_colour_ink_item(code):
                                    resolved.append(code)
                            if not resolved:
                                picked = search_flexo_ink_item_by_name(c_up)
                                if picked:
                                    resolved = [picked]
                            for ic in resolved:
                                ink_parts[ic] = ink_parts.get(ic, 0.0) + 1.0

                        if not ink_parts:
                            for ic in pick_default_flexo_ink_items(colour_count):
                                ink_parts[ic] = ink_parts.get(ic, 0.0) + 1.0
                        return ink_parts

                    def calc_flexo_bom_qty_per_kg(fabric_gsm):
                        f_gsm = float(fabric_gsm or 0)
                        if f_gsm <= 0:
                            return None
                        finished_gsm = f_gsm + FLEXO_INK_GSM_ADD
                        return {
                            "fabric_qty": round((f_gsm / finished_gsm) * 1.0, 5),
                            "ink_total": round((FLEXO_INK_GSM_ADD / finished_gsm) * 1.0, 5),
                            "iso_qty": round((FLEXO_ISOBUTANOL_GSM_ADD / finished_gsm) * 1.0, 5),
                        }

                    def resolve_flexo_isobutanol_item():
                        return pick_first_existing_item([
                            "INK - 1007091",
                            "ISOBUTANOL",
                            "ISO BUTANOL",
                            "ISO-BUTANOL",
                            "CM - ISOBUTANOL",
                        ])

                    def build_flexo_ink_recipe_for_row(row, fabric_gsm=None):
                        """Per-kg flexo printed fabric BOM: base fabric + flexo inks + isobutanol."""
                        f_gsm = float(fabric_gsm or 0)
                        if f_gsm <= 0:
                            f_gsm = float(row.get("custom_fabric_gsm") or 0)
                        if f_gsm <= 0:
                            f_gsm = float(row.get("custom_gsm") or 0)
                        qtys = calc_flexo_bom_qty_per_kg(f_gsm)
                        if not qtys:
                            return {"missing": ["Fabric GSM"]}

                        ink_parts = resolve_flexo_ink_parts(row)
                        existing_inks = []
                        for ic in ink_parts:
                            if frappe.db.exists("Item", ic) and is_flexo_colour_ink_item(ic) and not is_nonwoven_fabric_item_code(ic):
                                existing_inks.append(ic)
                        if not existing_inks:
                            defaults = pick_default_flexo_ink_items(1)
                            if defaults:
                                existing_inks = defaults[:1]
                                ink_parts = {defaults[0]: 1.0}

                        iso_item = resolve_flexo_isobutanol_item()
                        missing = []
                        if not existing_inks:
                            missing.append("Flexo INK (INK - 100xxxx)")
                        if not iso_item:
                            missing.append("INK - 1007091 / ISOBUTANOL")

                        parts_total = 0.0
                        for ic in existing_inks:
                            parts_total += float(ink_parts.get(ic, 0.0))
                        if parts_total <= 0:
                            parts_total = float(len(existing_inks) or 1)
                        ink_lines = []
                        for ic in existing_inks:
                            ink_lines.append({
                                "item_code": ic,
                                "qty": round(qtys["ink_total"] * float(ink_parts.get(ic, 0.0)) / parts_total, 5),
                            })
                        return {
                            "base_qty": qtys["fabric_qty"],
                            "ink_lines": ink_lines,
                            "iso_item": iso_item,
                            "iso_qty": qtys["iso_qty"],
                            "missing": missing,
                        }

                    def flexo_fabric_bom_missing_ink(bom_name):
                        """True when BOM has no INK - 100* colour ink or uses wrong items (fabric/BOPP)."""
                        if not bom_name:
                            return True
                        items = frappe.get_all(
                            "BOM Item", filters={"parent": bom_name}, fields=["item_code", "bom_no"]
                        )
                        if not items:
                            return True
                        has_flexo_colour_ink = False
                        for bi in items:
                            ic = str(bi.get("item_code") or "").strip()
                            if not ic:
                                continue
                            if ic in FLEXO_BOPP_SOLVENT_CODES or is_bopp_ink_item(ic):
                                return True
                            item_name = frappe.db.get_value("Item", ic, "item_name")
                            if is_bopp_ink_item(ic, item_name):
                                return True
                            if is_flexo_isobutanol_item(ic):
                                continue
                            if not bi.get("bom_no") and is_nonwoven_fabric_item_code(ic):
                                return True
                            if is_flexo_colour_ink_item(ic, item_name):
                                has_flexo_colour_ink = True
                            elif not bi.get("bom_no") and not is_flexo_isobutanol_item(ic):
                                return True
                        return not has_flexo_colour_ink

                    def ensure_flexo_printed_fabric_bom(fabric_item_code, base_fabric_item_code, base_bom_no, row, doc, fabric_gsm=None):
                        """Create or rebuild flexo printed fabric BOM with base fabric + flexo ink + isobutanol."""
                        if not base_bom_no or not fabric_item_code:
                            return None
                        fab_bom_no = frappe.db.get_value(
                            "BOM",
                            {"item": fabric_item_code, "is_active": 1, "is_default": 1, "docstatus": 1},
                            "name",
                        )
                        if not fab_bom_no:
                            fab_bom_no = frappe.db.get_value(
                                "BOM", {"item": fabric_item_code, "is_active": 1, "docstatus": 1}, "name"
                            )
                        if fab_bom_no and not flexo_fabric_bom_missing_ink(fab_bom_no):
                            return fab_bom_no
                        if fab_bom_no and flexo_fabric_bom_missing_ink(fab_bom_no):
                            try:
                                old_bom = frappe.get_doc("BOM", fab_bom_no)
                                if old_bom.docstatus == 1:
                                    old_bom.cancel()
                            except Exception as e:
                                frappe.log_error(
                                    "Flexo fabric BOM cancel failed for " + str(fabric_item_code), str(e)
                                )
                        recipe = build_flexo_ink_recipe_for_row(row, fabric_gsm=fabric_gsm)
                        if recipe.get("missing"):
                            frappe.log_error(
                                "Flexo Printed Fabric BOM Skipped: Missing items: " + ", ".join(recipe["missing"]),
                                str(fabric_item_code),
                            )
                            return fab_bom_no
                        try:
                            fab_bom = frappe.new_doc("BOM")
                            fab_bom.company = doc.company
                            fab_bom.item = fabric_item_code
                            fab_bom.quantity = 1.0
                            fab_bom.is_default = 1
                            fab_bom.is_active = 1
                            fab_bom.currency = "INR"
                            fab_bom.rm_cost_as_per = "Valuation Rate"
                            fab_bom.append(
                                "items",
                                {
                                    "item_code": base_fabric_item_code,
                                    "bom_no": base_bom_no,
                                    "qty": float(recipe["base_qty"]),
                                    "uom": "Kg",
                                    "do_not_explode": 1,
                                },
                            )
                            for ink_line in recipe.get("ink_lines") or []:
                                fab_bom.append(
                                    "items",
                                    {
                                        "item_code": ink_line["item_code"],
                                        "qty": float(ink_line["qty"]),
                                        "uom": "Kg",
                                    },
                                )
                            iso_item = recipe.get("iso_item")
                            if iso_item:
                                fab_bom.append(
                                    "items",
                                    {"item_code": iso_item, "qty": float(recipe.get("iso_qty") or 0), "uom": "Kg"},
                                )
                            safe_item_insert(fab_bom)
                            fab_bom.submit()
                            return fab_bom.name
                        except Exception as e:
                            frappe.log_error(
                                "Failed to create Flexo Printed Fabric BOM for " + str(fabric_item_code), str(e)
                            )
                            return fab_bom_no

