                                final_design_name = str(row.get("custom_design_name") or row.get("custom_design_name") or "").strip().upper()

                                bopp_quality_code_map = {
                                    "PREMIUM": "A", "PLATINUM": "B", "SUPER PLATINUM": "C",
                                    "GOLD": "D", "SILVER": "E", "BRONZE": "F",
                                    "CLASSIC": "G", "SUPER CLASSIC": "H", "LIFE STYLE": "I",
                                    "LIFESTYLE": "I", "ECO SPECIAL": "J", "ECO GREEN": "K",
                                    "SUPER ECO": "L", "ULTRA": "M", "DELUXE": "N",
                                    "VIRGIN MIX - GOLD MIX": "O", "MID MIX - CLASSIC MIX": "P",
                                    "ECO MIX": "Q", "DELUXE MIX": "R"
                                }
                                bopp_q_code = bopp_quality_code_map.get(q, "X")
                                bopp_c_code = c_code

                                fabric_gsm_code_map = {
                                    20: "A", 25: "B", 30: "C", 35: "D", 40: "E",
                                    45: "F", 50: "G", 55: "H", 60: "I", 65: "J",
                                    70: "K", 75: "L", 80: "M", 85: "N", 90: "O",
                                    95: "P", 100: "Q", 105: "R", 110: "S", 115: "T", 120: "U"
                                }

                                bopp_gsm_code_map = {10: "A", 12: "B", 15: "C", 30: "D", 0: "0"}
                                bopp_gsm_raw = str(row.get("custom_bopp_gsm") or "0").strip()
                                bopp_gsm_digits = "".join(ch for ch in bopp_gsm_raw if ch.isdigit())
                                bopp_num_val = int(bopp_gsm_digits) if bopp_gsm_digits else 0
                                bopp_bopp_gsm_code = bopp_gsm_code_map.get(bopp_num_val, str(bopp_num_val))

                                lam_gsm_code_map = {10: "A", 12: "B", 15: "C", 30: "D", 20: "E"}
                                lam_gsm_raw = str(row.get("custom_lamination_gsm") or "0").strip()
                                lam_gsm_digits = "".join(ch for ch in lam_gsm_raw if ch.isdigit())
                                lam_num_val = int(lam_gsm_digits) if lam_gsm_digits else 0
                                bopp_lam_gsm_code = lam_gsm_code_map.get(lam_num_val, str(lam_num_val))

                                fab_gsm_raw = str(row.get("custom_fabric_gsm") or "0").strip()
